import { onSceneShutdown } from "../../scenes";
import { UnSubManager } from "../../UnSubManager";
type Cleaner = { destroy: () => void } | (() => void);

/**
 *  Любой класс, который будет жить вместе с сценой или игровым объектом
 *  и уйдет вместе с ним, корректно отписываясь и очищаясь
 *
 *  Цель - подключать новые фичи и приколы к игре одной строкой
 *
 *  Никаких коллбэков - общение только через scene.gameEvents
 ***/
export class CoreBehavior {
  readonly type: string = "CoreBehavior";

  protected readonly unSubManager = new UnSubManager();
  protected readonly scene: Phaser.Scene;

  /** Синтаксический сахар для быстрого подключения инстанстов **/
  static enable(scene: Phaser.Scene, enabled: boolean, options?: Record<string, unknown>) {
    if (!enabled) return;
    return new this(scene, options);
  }

  constructor(
    protected host: Phaser.Scene | Phaser.GameObjects.GameObject,
    protected options?: Record<string, unknown>,
  ) {
    this.scene = host instanceof Phaser.Scene ? host : host.scene;
    if (host instanceof Phaser.Scene) {
      onSceneShutdown(host, () => this.destroy());
    } else {
      host.on(Phaser.GameObjects.Events.DESTROY, () => this.destroy());
    }
    this.create(this.scene);
  }

  /** При создании конкретного поведения - просто реализуйте этот метод **/
  create(scene: Phaser.Scene) {}

  addUnSub(clean: Cleaner | Cleaner[]) {
    this.unSubManager.addUnSub(clean);
  }

  destroy() {
    console.log(`destroy behavior ${this.type}`);
    this.unSubManager.clear();
  }

  /** @deprecated **/
  getObject<T extends Phaser.GameObjects.GameObject>(name: string): T | undefined {
    return this.scene.children.getByName(name) as T | undefined;
  }

  /** @deprecated **/
  getObjects<T extends Phaser.GameObjects.GameObject>(name: string): T[] {
    return this.scene.children.getAll("name", name) as T[];
  }
}
