import { IClassicCardDto } from "../../../common";
import { KlondikeStateStep } from "../../../common/games/cards-klondike-v2/types";
import { GoodyType } from "../../../logic";

export enum ConsumableType {
  UNDO = "UNDO",
  HINT = "HINT",
  MAGIC = "MAGIC",
  VISION = "VISION",
}

export interface IConsumableState {
  isPossible: boolean;
  balance: number;
}

export type ConsumableStateRecord = Record<ConsumableType, IConsumableState>;

export interface GameLogicState {
  consumableBalance: Record<ConsumableType, number>;
  consumableButtonsEnabled: Record<ConsumableType, boolean>;
  showGoodyOverlay?: { goody: GoodyType; durationMs?: number };
  showShopOverlay?: {};
  score: number;
}

export interface IMinMax {
  min: number;
  max: number;
}

export interface ILootConfig {
  lootProbability: Record<ConsumableType, number>;
  lootMultipliers: number[];
  lootDispersion: number;
}

export interface GameLogicConfig {
  lootConfig: ILootConfig,
  klondikeConfig: {
    hintDurationMs: number;
    magicTrickDurationMs: number;
    visionTrickDurationMs: number;
  };
}

/** Эвенты с описанием данных от View - читаются в логике **/
export interface IGameViewEvents {
  klondikeStateUpdate: {
    isUndoPossible: boolean;
    isHintPossible: boolean;
    isMagicPossible: boolean;
    isVisionPossible: boolean;
    step: KlondikeStateStep;
    score: number;
  };
  klondikeDealFinish: void;
  klondikeUndoFinish: void;
  klondikeMagicFinish: void;
  klondikeVisionFinish: void;
  klondikeHintFinish: void;
  klondikeCompleted: void;

  /** Ui **/
  uiNewGameClick: void;
  uiReplayClick: void;
  uiUndoClick: void;
  uiHintClick: void;
  uiVisionClick: void;
  uiMagicClick: void;
}

