/** Команды с данными от логики для вью **/
export interface IGameLogicCommandEvents {
  startKlondike: { cards: IClassicCardDto[] };
  undoKlondike: void;
  hintKlondike: { durationMs: number };
  visionKlondike: { durationMs: number };
  magicKlondike: { durationMs: number };
  showGameFinish: { loots: Record<ConsumableType, number>[]; score: number };
}

