import { GameService, IGameServiceOptions } from "./GameService";
import { gameConfig } from "../../config";

const defaultProps: IGameServiceOptions = {
  appId: gameConfig.gameId
}

export class GameServiceProvider {
  private static gameService: GameService;

  /** старайся использовтаь это только в крупных компонентах
   * и связанных с реализацией конкретной игры
   * **/
  static get(options?: IGameServiceOptions ): GameService {
    if(this.gameService==null){
      this.gameService = new GameService({ ...defaultProps, ...options });
    }
    return this.gameService;
  }

  static reset(options?: IGameServiceOptions ): GameService {
    this.gameService = new GameService({ ...defaultProps, ...options });
    return this.gameService;
  }
}
