import { CardValue, makeGrid } from "../../../../../common";
import { Align, ISizeable } from "@kvisaz/phaser-sugar";

interface IProps {
  value: CardValue;
  align: Align;
  builder: () => Phaser.GameObjects.Image;
}

const getOffsets = (image: ISizeable) => {
  const { width, height } = image.getBounds();

  return {
    commonOffsetY: height * 0.5,
    pairOffsetX: width,
    pairOffsetY: height * 1.3,
    nineOffsetY: height * 1.2,
    maxOffsetY: width * 3,
    sevenCenterOffsetY: height * 0.6,
  };
};

export function layoutNumberCard({ value, align, builder }: IProps) {
  let images: Phaser.GameObjects.Image[] = [];

  if (value === "ace") {
    images = [builder().setScale(2.5)
      .setAlpha(0.2),
      builder().setScale(2)];
  }

  if (value === 2) {
    images = [builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    align.anchor(images[0]).centerX(images[1]).bottomTo(images[1], layoutConfig.pairOffsetY);
  }

  if (value === 3) {
    images = [builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    align.anchor(images[0]).centerX(images[1]).bottomTo(images[1], layoutConfig.pairOffsetY);
    align.anchor({ getBounds: () => combineBounds(images) }).center(images[2]);
  }

  if (value === 4) {
    images = [builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    align.anchor(images[0]).rightTo(images[1], layoutConfig.pairOffsetX).centerY(images[1]);
    align.anchor(images[0]).centerX(images[2]).bottomTo(images[2], layoutConfig.pairOffsetY);
    align.anchor(images[2]).rightTo(images[3], layoutConfig.pairOffsetX).centerY(images[3]);
  }

  if (value === 5) {
    images = [builder(), builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    align.anchor(images[0]).rightTo(images[1], layoutConfig.pairOffsetX).centerY(images[1]);
    align.anchor(images[0]).centerX(images[2]).bottomTo(images[2], layoutConfig.pairOffsetY);
    align.anchor(images[2]).rightTo(images[3], layoutConfig.pairOffsetX).centerY(images[3]);
    align.anchor({ getBounds: () => combineBounds(images) }).center(images[4]);
  }

  if (value === 6) {
    images = [builder(), builder(), builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    makeGrid({
      objects: images,
      unitInRow: 2,
      colStep: layoutConfig.pairOffsetX * 2,
      rowStep: layoutConfig.pairOffsetY,
    });
  }

  if (value === 7) {
    images = [builder(), builder(), builder(), builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    makeGrid({
      objects: images,
      unitInRow: 2,
      colStep: layoutConfig.pairOffsetX * 2,
      rowStep: layoutConfig.pairOffsetY,
    });
    align
      .anchor({ getBounds: () => combineBounds(images.slice(0, 6)) })
      .center(images[6], 0, -layoutConfig.sevenCenterOffsetY);
  }

  if (value === 8) {
    images = [builder(), builder(), builder(), builder(), builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    makeGrid({
      objects: images,
      unitInRow: 2,
      colStep: layoutConfig.pairOffsetX * 2,
      rowStep: layoutConfig.pairOffsetY,
    });
    align
      .anchor({ getBounds: () => combineBounds(images.slice(0, 6)) })
      .center(images[6], 0, -layoutConfig.sevenCenterOffsetY);
    align.center(images[7], 0, layoutConfig.sevenCenterOffsetY);
  }

  if (value === 9) {
    images = [builder(), builder(), builder(), builder(), builder(), builder(), builder(), builder(), builder()];
    const layoutConfig = getOffsets(images[0]);
    makeGrid({
      objects: images,
      unitInRow: 2,
      colStep: layoutConfig.pairOffsetX * 2,
      rowStep: layoutConfig.nineOffsetY,
    });
    align.anchor({ getBounds: () => combineBounds(images.slice(0, 8)) }).center(images[8]);
  }

  if (value === 10) {
    images = [
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
      builder(),
    ];
    const layoutConfig = getOffsets(images[0]);
    makeGrid({
      objects: images,
      unitInRow: 2,
      colStep: layoutConfig.pairOffsetX * 2,
      rowStep: layoutConfig.nineOffsetY,
    });
    align
      .anchor({ getBounds: () => combineBounds(images.slice(0, 8)) })
      .center(images[8], 0, -layoutConfig.nineOffsetY);
    align.center(images[9], 0, layoutConfig.nineOffsetY);
  }

  return images;
}

/** todo move to Phaser Sugar **/
export function combineBounds(images: { getBounds(): Phaser.Geom.Rectangle }[]): Phaser.Geom.Rectangle {
  if (images.length === 0) {
    console.warn("getBounds: no images");
    return new Phaser.Geom.Rectangle(0, 0, 0, 0);
  }

  const bounds = images.map((image) => image.getBounds());
  const first = bounds[0];
  if (bounds.length === 1) return first;

  let combined = first;
  for (let i = 1; i < bounds.length; i++) {
    combined = Phaser.Geom.Rectangle.Union(combined, bounds[i]);
  }
  return combined;
}
