import { ExternalTopbarDialog } from "../../../../common/game-core";
import { OverlayScene } from "../../../../common/scenes";
import { LootBoxes, LootParticles, LootSideBar } from "./components";
import { Align, AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { getLocalizedText, ViewElementBuilder } from "../../../../assets";
import { ConsumableType } from "../../logic";
import { shuffleArray } from "../../../../common";
import { ILootDto, LootItemType, SoundKey } from "../../../../logic";
import { GameServiceProvider } from "../../../../services";

export interface IGameFinishData {
  /** награды в сундуках - количество сундуков в зависимости от массива **/
  loots: Record<ConsumableType, number>[];
  score: number;
}

interface IProps {
  scene: Phaser.Scene;
}

/**
 * Показать результат
 * - показать сундуки в диалоге
 * - компоненты экрана сами читают данные
 * **/
export class GameFinishOverlay {
  private readonly unSubs: (() => void)[] = [];
  private align = new Align();
  private dialog?: ExternalTopbarDialog;
  private builder: ViewElementBuilder;
  private particles: LootParticles | undefined;

  constructor(private props: IProps) {
    /** overlay автоматически отключится вместе со сценой **/
    const parentScene = this.props.scene;
    OverlayScene.attach(parentScene);

    const childScene = OverlayScene.get(this.props.scene);
    this.builder = new ViewElementBuilder(childScene);
  }

  showScreen(data: IGameFinishData) {
    /** экран показываем в child **/
    const childScene = OverlayScene.get(this.props.scene);
    this.pauseParentScene();
    childScene.sound.play(SoundKey.fanfare);
    this.create(childScene, data);
  }

  closeScreen() {
    this.clearScene();
  }

  private clearScene() {
    const childScene = OverlayScene.get(this.props.scene);
    this.dialog?.destroy();
    childScene.children.removeAll();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
    this.resumeParentScene();
  }

  /***
   Private
   ***/

  /** создать в child scene **/
  private create(scene: Phaser.Scene, data: IGameFinishData) {
    this.dialog?.destroy();
    const dialogContent = this.createDialogContent(scene, data);
    this.dialog = this.createDialog(scene, dialogContent);
    this.dialog.show();

    /** в этой же сцене создаются слои **/
    this.createSidebar(scene);
    this.createLootParticles(scene);
  }

  private pauseParentScene() {
    this.props.scene.scene.pause();
  }

  private resumeParentScene() {
    this.props.scene.scene.resume();
  }

  private createSidebar(scene: Phaser.Scene) {
    const lootSideBar = new LootSideBar({ scene });

    const { align } = this;
    align.anchorSceneScreen(scene).leftIn(lootSideBar, 33).bottomIn(lootSideBar, -86);
  }

  private createDialog(scene: Phaser.Scene, dialogContent: Phaser.GameObjects.Container) {
    const builder = new ViewElementBuilder(scene);

    const title = getLocalizedText("gameOver.congratulation");
    const dialogWidth = 1100;
    const dialogHeight = 700;

    const beforeOpen = () => {};
    const onClose = () => {
      this.clearScene();
    };

    const dialog = builder.dialogExternalTopTitle({
      beforeOpen,
      content: dialogContent,
      title,
      width: dialogWidth,
      height: dialogHeight,
      onClose,
    });
    return dialog;
  }

  private createDialogContent(scene: Phaser.Scene, data: IGameFinishData) {
    const content = new Phaser.GameObjects.Container(scene);
    const { align, builder } = this;

    /** scoreText **/
    const scoreText = getLocalizedText("gameOver.info", { score: data.score });
    const scoreTextView = builder.textDialog(scoreText, {
      color: "rgb(0,0,0)",
      weight: "semibold",
      fontSize: "48px",
    });

    /** loot Text **/
    const lootText = getLocalizedText("gameOver.lootInvite");
    const lootTextView = builder.textDialog(lootText, {
      color: "rgb(140,9,9)",
      weight: "semibold",
      fontSize: "48px",
    });

    /** buttons **/
    const buttonWidth = 300;
    const buttonHeight = 120;

    /** флаг для сценария: если юзер жмёт OK до клика по сундуку — открываем рандомный сундук и закрываем по завершению анимаций **/
    let closeAfterCollect = false;
    const requestCloseAfterCollect = () => {
      closeAfterCollect = true;
    };

    /**
     * multiply reward button
     * - должна показываться только если
     * **/
    const rewardText = getLocalizedText("gameOver.lootDouble");
    const rewardButton = builder.buttonPrimary(rewardText, () => {
      // отключаем кнопку после нажатия
      rewardButton.disableInteractive();
      /**
       *  todo показать рекламу с вознаграждением
       *  через GameService
       **/
    }, {
      width: buttonWidth * 1.2,
      height: buttonHeight
    });
    // по умолчанию прячем кнопку
    rewardButton.setAlpha(0);

    /** кнопка должна показываться только если реклама разрешена **/
    function tryShowDoubleRewardButton() {
      if (!GameServiceProvider.get().isRewardAdEnabled) return;
      rewardButton.setAlpha(1);
    }

    /** loots **/
    const loots: ILootDto[] = this.calcRandomLoots(data);
    const lootBoxes = new LootBoxes({
      scene,
      amount: data.loots.length,
      onLootBoxClick: (clickedBounds) => {
        scene.sound.play(SoundKey.chestSlam);
        const shouldClose = closeAfterCollect;
        closeAfterCollect = false;
        this.particles?.emit({
          loots,
          clickedBounds,
          onComplete: shouldClose ? () => this.dialog?.close() : undefined,
        });
        if (this.particles == null && shouldClose) {
          this.dialog?.close();
        }
        tryShowDoubleRewardButton();
      },
    });
    lootBoxes.startShaking();

    /** restart game button **/
    const restartButtonText = getLocalizedText("ok").toUpperCase();
    const restartButton = builder.buttonSecondary(
      restartButtonText,
      () => {
        this.onRestartButtonClick({ restartButton, lootBoxes, requestCloseAfterCollect });
      },
      {
        width: buttonWidth,
        height: buttonHeight,
      },
    );

    const children = [scoreTextView, lootTextView, lootBoxes, rewardButton, restartButton];

    layoutChain({
      children,
      alignToAnchor: AlignMethod.CENTER_X,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 24,
    });

    content.add(children);
    return content;
  }

  private calcRandomLoots(data: IGameFinishData) {
    const shuffledLootsData = shuffleArray([...data.loots]);
    const clickedLoot = shuffledLootsData[0];
    const loots: ILootDto[] = [
      {
        type: LootItemType.HINT,
        amount: clickedLoot.HINT,
      },
      {
        type: LootItemType.UNDO,
        amount: clickedLoot.UNDO,
      },
      {
        type: LootItemType.MAGIC,
        amount: clickedLoot.MAGIC,
      },
      {
        type: LootItemType.VISION,
        amount: clickedLoot.VISION,
      },
    ].filter((dto) => dto.amount > 0);

    return loots;
  }

  private createLootParticles(scene: Phaser.Scene) {
    const sideBar = scene.children.getByName("LootSideBar") as LootSideBar | null;
    this.particles = new LootParticles({
      scene,
      onLootItemCollectStart: (lootDto) => {
        //
      },
      onLootItemCollected: (lootDto) => {
        scene.sound.play(SoundKey.coinFlip);
        sideBar?.collect(lootDto);
      },
    });
  }

  private onRestartButtonClick(args: {
    restartButton: Phaser.GameObjects.GameObject;
    lootBoxes: LootBoxes;
    requestCloseAfterCollect: () => void;
  }) {
    const { restartButton, lootBoxes, requestCloseAfterCollect } = args;

    restartButton.disableInteractive();

    if (lootBoxes.hasOpenedChest()) {
      this.dialog?.close();
      return;
    }

    requestCloseAfterCollect();
    lootBoxes.openRandomChest();
  }

}
