import { GameLogicState } from "../logic";
import { ViewElementBuilder } from "../../../assets";
import { Observable } from "../../../common";
import { GoodyType } from "../../../logic";
import { OverlayScene } from "../../../common/scenes";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<GameLogicState>;
}

export class ConsumableOverlays {
  private readonly unSubs: (() => void)[] = [];
  private overlay: Phaser.GameObjects.GameObject | undefined;

  constructor(private readonly props: IProps) {
    /** overlay автоматически отключится вместе со сценой **/
    OverlayScene.attach(this.props.scene);
    /** но на случай сторибука  - включим отдельное разрушение **/
    this.unSubs.push(() => OverlayScene.destroy());
    this.unSubs.push(this.props.gameState.on((state) => this.apply(state.showGoodyOverlay)));
    this.apply(this.props.gameState.getState().showGoodyOverlay);
  }

  destroy() {
    this.unSubs.forEach((u) => u());
  }

  private apply(config?: { goody: GoodyType; durationMs?: number }) {
    if (!config) {
      this.overlay?.destroy();
      this.overlay = undefined;
      return;
    }

    this.overlay?.destroy();
    this.overlay = new ViewElementBuilder(OverlayScene.get(this.props.scene)).effectGoody(config);
  }
}
