  /** Private helpers **/
  private consumableButton({
    name,
    onClick,
    imageAsset,
  }: {
    imageAsset: ImageAsset;
    onClick: () => void;
    name: string;
  }) {
    const nineSliceAsset = AssetsConfig.images.uiUsefulBgNine32;

    return this.addButtonSound(
      new ConsumableButton({
        name,
        scene: this.scene,
        onClick: () => {
          onClick();
        },
        initAmount: 0,
        buttonImageBuilder: () => this.image(imageAsset),
        textBgBuilder: (width, height) =>
          this.nineSlice({ ...nineSliceAsset, width, height, padding: 32 }),
        textBuilder: (text) => this.textResourceCounter(text),
      }),
    );
  }

  private imageButton(
    imageAsset: ImageAsset,
    onClick: () => void,
    options: { once?: boolean; scale?: number } = {},
  ) {
    const { once = false, scale = 1 } = options;
    const image = this.image(imageAsset);

    const button = this.addButtonSound(
      new CenteredContainerButton({
        gameObjects: [image],
        onClick,
        options: {
          once,
          onDisabled: () => image.setTint(0xdedede),
          onEnabled: () => image.clearTint(),
          disableAfterClick: {
            ms: 100,
          },
        },
      }),
    );

    button.setScale(scale);

    return button;
  }

  private textButton(text: string, onClick: () => void, imageAsset: ImageAsset, options?: ITextButtonOptions) {

    let textOptions: ITextBuildProps|undefined;
    if(options?.width){
      const textWidth = options.width * 0.8;
      textOptions = {
        fixedWidth: textWidth,
        wordWrap: {
          width: textWidth
        }
      }
    }

    const textLabel = this.textButtonBasic(text, textOptions);
    const textBounds = textLabel.getBounds();
    console.log('textButton options?.padding', options?.paddingX);
    const minWidth = 220;
    const paddingX = options?.paddingX ?? 32;
    const paddingY = options?.paddingY ?? 0;
    const width = options?.width ?? Math.max(minWidth, textBounds.width + 2 * paddingX);
    const height = options?.height ?? 80 + 2 * paddingY;
    const bg = this.nineSlice({ ...imageAsset, width, height, padding: 32 });

    return this.addButtonSound(
      new CenteredContainerButton({
        gameObjects: [bg, textLabel],
        onClick,
        options: {
          disableAfterClick: {
            ms: 0,
          },
          once: false,
          onDisabled: (button) => button.setAlpha(0.8),
          onEnabled: (button) => button.setAlpha(1),
        },
      }),
    );
  }

  private image({ url, frameName }: ImageAsset) {
    return this.scene.add.existing(new Phaser.GameObjects.Image(this.scene, 0, 0, url, frameName));
  }

  private nineSlice({ url, frameName, width, height, padding = 20 }: INineSliceAsset) {
    return this.scene.add.existing(
      new Phaser.GameObjects.NineSlice(
        this.scene,
        0,
        0,
        url,
        frameName,
        width,
        height,
        padding,
        padding,
        padding,
        padding,
      ),
    );
  }
