import { Info } from "./Info";

interface IProps {
  scene: Phaser.Scene;
  score: number;
  textPrefix: string;
  bgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
}

/** Информационные табло - текст и фон **/
export class GameSessionScoreInfo extends Info {
  protected textPrefix: string;

  constructor({ score, textPrefix, ...props }: IProps) {
    super({
      initText: "",
      ...props,
    });
    this.textPrefix = textPrefix;
    this.setScore(score);
  }

  setScore(score: number) {
    const text = `${this.textPrefix} ${score}`;
    this.setText(text);
  }
}
