import { AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../../../../assets";
import {
  Anima,
  finishAnimation,
  GameObject,
  getCycled,
  killAnimation, LootBox,
  sceneTimeout,
  shuffleArray
} from "../../../../../../common";

interface IProps {
  scene: Phaser.Scene;
  onLootBoxClick?: (clickedBounds: Phaser.Geom.Rectangle)=>void;
  amount?: number;
  shakingDuration?: number;
  singleShakingIntervalMs?: number;
  padding?: number;
}

export class LootBoxes extends Phaser.GameObjects.Container {
  private isSomeOpened = false;
  private lootBoxes: LootBox[];

  constructor(private props: IProps) {
    super(props.scene);

    const { scene, amount, padding = 32, onLootBoxClick } = props;
    const builder = new ViewElementBuilder(scene);

    const buildLootBox = () => {
      const lootBox = builder.lootBox();

      if(onLootBoxClick){
        lootBox.setInteractive({
          useHandCursor: true
        });
        lootBox.once(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, ()=>this.onLootBoxClicked(lootBox));
      }

      return lootBox;
    };

    const lootBoxes = Array.from(new Array(amount)).map((_) => buildLootBox());
    layoutChain({
      children: lootBoxes,
      alignToAnchor: AlignMethod.CENTER_Y,
      alignToNext: AlignMethod.RIGHT_TO,
      nextOffsetX: padding,
    });

    this.add(lootBoxes);
    this.lootBoxes = lootBoxes;
    scene.add.existing(this);
  }

  hasOpenedChest() {
    return this.isSomeOpened;
  }

  /** открыть случайный сундук (если ещё ни один не открыт) **/
  openRandomChest() {
    if (this.isSomeOpened) return;
    const lootBox = Phaser.Utils.Array.GetRandom(this.lootBoxes);
    if (!lootBox) return;
    this.onLootBoxClicked(lootBox);
  }

  startShaking() {
    const { singleShakingIntervalMs = 800, shakingDuration } = this.props;
    const { lootBoxes } = this;
    const shuffled = shuffleArray([...lootBoxes]);
    let startIndex = 0;

    const getTarget = () => {
      return getCycled(shuffled, startIndex++);
    };

    const setShakeTimer = (delay = 0) => {
      const { scene, isSomeOpened } = this;
      if (scene == null) return;
      sceneTimeout({
        scene,
        delay,
        callback: () => {
          if (this.isSomeOpened) return;
          Anima.shakeLootBox({
            target: getTarget(),
            duration: shakingDuration,
            onComplete: () => {
              if (isSomeOpened) return;
              setShakeTimer(singleShakingIntervalMs);
            },
          });
        },
      });
    };

    setShakeTimer();
  }

  private onLootBoxClicked(lootBox: LootBox){
    this.lootBoxes.forEach(box=> {
      finishAnimation(box);
      box.disableInteractive();
    });
    lootBox.open();
    this.isSomeOpened = true;
    this.props.onLootBoxClick?.(lootBox.getBounds());
  }
}
