import {
  animateCardFlip,
  animateCardMove,
  CardsMoveDealer,
  delayScenic,
  IAbstractCard,
  ICardStack,
  IKlondikeMoveDealerConfig,
  layoutForAnimation,
  shuffleArray,
} from "../../../../../common";
import { SoundKey } from "../../../../../logic";

const defaultDealConfig = {
  layoutFromDuration: 100,
  moveDuration: 150,
  flipDuration: 100,
  cardStepDuration: 100,
};

/**  функция раздачи карт с изменением стопок и анимациями
 *  НЕ НАДО ее делать абстрактной
 *  она конкретна для игры
 *  копипасть и переиспользуй
 * **/
export const dealKlondikeCards: CardsMoveDealer = async (
  deck,
  piles,
  options?: Partial<IKlondikeMoveDealerConfig>,
): Promise<void> => {
  const scene = deck.cards[0]?.scene;
  if (scene == null) return;

  const config: IKlondikeMoveDealerConfig = {
    ...defaultDealConfig,
    ...options,
  };

  if (config.shuffling) {
    shuffleArray(deck.cards);
  }
  deck.layout();

  const pilesAmount = piles.length;
  for (let row = 0; row < pilesAmount; row++) {
    for (let pileIndex = row; pileIndex < pilesAmount; pileIndex++) {
      const nextCard = deck.topCard;
      const toStack = piles[pileIndex];
      if (nextCard == null || toStack == null) continue;

      if (config.cardStepDuration > 0) {
        await delayScenic(config.cardStepDuration, scene);
        scene.sound.play(SoundKey.cardFlip);
      }

      dealCard({ card: nextCard, from: deck, to: toStack, flip: pileIndex === row, config }).catch(
        console.warn,
      );
    }
  }
};

async function dealCard(args: {
  card: IAbstractCard;
  from: ICardStack;
  to: ICardStack;
  flip: boolean;
  config: IKlondikeMoveDealerConfig;
}) {
  const { card, from, to, flip, config } = args;

  from.removeCard(card);
  to.placeCards([card]);

  /**  проводим лейаут для исходного стека **/
  const fromLayoutParams = layoutForAnimation({
    cards: from.cards,
    layout: () => from.layout(),
  });

  /** делаем лейаут для целевого стека запоминая разницу между позициями **/
  const moveParams = layoutForAnimation({
    cards: [card],
    layout: () => to.layout(),
  });

  const { moveDuration, layoutFromDuration, flipDuration } = config;

  /** если не анимировано - финиш **/
  if (moveDuration == null || moveDuration === 0) return;

  const promises = [
    /** анимация полета карты в новый стек **/
    animateCardMove({
      moveParams,
      duration: moveDuration,
    }),
    /** анимация лейаута исходного стека - ему возможно надо восстановиться **/
    animateCardMove({
      moveParams: fromLayoutParams,
      duration: layoutFromDuration ?? 0,
    }),
  ];

  if (flip) {
    promises.push(
      animateCardFlip({
        card,
        flipTo: "face",
        duration: flipDuration,
      }),
    );
  }

  /** делаем анимацию на основе разницы **/
  await Promise.all(promises);
}
