import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../../assets";
import { OverlayScene } from "../../../../common/scenes";
import { mockShopData } from "../../../../logic";
import { ExternalTopbarDialog, IShopItem } from "../../../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
}

/**
 *  Кнопка магазина
 *  и диалог магазина который вызывается по нажатию на кнопку
 *  магазин читает данные из сервисов
 *  - PlayerDataService
 *  - ShopDataService
 *
 *  отправляет данные в
 *  - ShopDataService - о желании покупки
 *  - PlayerDataService - о зачислении покупки
 **/
export class ShopOverlay extends Phaser.GameObjects.Container {
  /** нужно только для открытия диалога в окне поверх **/
  private readonly unSubs: Array<() => void> = [];
  private dialog: ExternalTopbarDialog;

  constructor(private readonly props: IProps) {
    super(props.scene);

    const builder = new ViewElementBuilder(props.scene);
    const align = new Align();
    const button = builder.buttonShop(() => this.dialog.show());
    align.anchor(this).topIn(button).leftIn(button);
    this.add(button);
    this.scene.add.existing(this);

    this.dialog = this.createDialogOverlay();
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
  }

  private createDialogOverlay() {
    const { scene } = this.props;
    /** overlay автоматически отключеится вместе со сценой **/
    const overlayScene = OverlayScene.get(scene);
    /** но на случай сторибука  - включим отдельное разрушение **/
    this.unSubs.push(() => OverlayScene.destroy());

    const overlayBuilder = new ViewElementBuilder(overlayScene);
    this.dialog = overlayBuilder.dialogShop({
      items: mockShopData.gameShopItems,
      onItemBuyClick: this.onItemBuyClick.bind(this),
      onClose: this.onClose.bind(this),
    });
    return this.dialog;
  }

  private onItemBuyClick(item: IShopItem) {
    console.log(`click on  ${item.id} ${item.price}`);
  }

  private onClose() {
    console.log("onClose dsxcxc");
  }
}
