import { AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { Anima, createGO } from "../../../../../../common";
import { ViewElementBuilder } from "../../../../../../assets";
import { ILootDto, LootTargetRecord } from "../../../../../../logic";
import { GameServiceProvider } from "../../../../../../services";
import { ConsumableButton } from "../../../../../../assets/builders/ViewElementBuilder/components/ConsumableButton";
import { ConsumableType } from "../../../../logic";

interface IProps {
  scene: Phaser.Scene;
}

const CLASS_NAME = "LootSideBar";

/**
 * Сайдбар с бонусами
 * - показывает их актуальное количество у игрока
 * - при пополнении обновляет данные у игрока через GameService
 *  (debounce на стороне сервиса - обновлять здесь можно как угодно часто)
 **/
export class LootSideBar extends Phaser.GameObjects.Container {
  private readonly lootTargets: Record<ConsumableType, ConsumableButton>;
  name = CLASS_NAME;

  private consumablesState: Record<ConsumableType, number>;

  constructor(private props: IProps) {
    super(props.scene);
    const { consumables } = GameServiceProvider.get().getPlayerData();
    this.consumablesState = { ...consumables };

    this.lootTargets = this.createButtons(consumables);
    const buttons = Object.values(this.lootTargets);
    layoutChain({
      children: buttons,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 20,
      alignToAnchor: AlignMethod.LEFT_IN,
    });
    this.add(buttons);
    this.scene.add.existing(this);
  }

  getLootTargets(): LootTargetRecord {
    return this.lootTargets;
  }

  collect({ type, amount }: ILootDto) {
    const target = this.lootTargets[type];
    if (target == null) {
      console.warn("unknown target in LootSideBar", type);
      return;
    }
    target.incAmount(amount);
    this.consumablesState[type] += amount;
    this.saveData();
    Anima.popItem({ target, scaleAmount: 1.2 });
  }

  private createButtons(consumables: Record<ConsumableType, number>) {
    const { scene } = this.props;
    const builder = new ViewElementBuilder(scene);

    const lootTargets: Record<ConsumableType, ConsumableButton> = {
      [ConsumableType.UNDO]: createGO(() => builder.buttonUndo(() => {}), {
        use: (button) => {
          button.disableInteractive();
          button.setAmount(consumables.UNDO);
        },
      }),
      [ConsumableType.HINT]: createGO(() => builder.buttonHint(() => {}), {
        use: (button) => {
          button.disableInteractive();
          button.setAmount(consumables.HINT);
        },
      }),
      [ConsumableType.VISION]: createGO(() => builder.buttonVision(() => {}), {
        use: (button) => {
          button.disableInteractive();
          button.setAmount(consumables.VISION);
        },
      }),
      [ConsumableType.MAGIC]: createGO(() => builder.buttonMagic(() => {}), {
        use: (button) => {
          button.disableInteractive();
          button.setAmount(consumables.MAGIC);
        },
      }),
    };
    return lootTargets;
  }

  private saveData() {
    const gameService = GameServiceProvider.get();
    gameService.setPlayerData({ consumables: { ...this.consumablesState } });
  }
}

export function isLootSidebar(
  obj: Phaser.GameObjects.GameObject | undefined | null,
): obj is LootSideBar {
  return obj?.type === CLASS_NAME;
}
